    resume: Option<&Resume>,
    let mut events = vec![HarnessEvent::ToolStarted {
        id: id.clone(),
        name: name.to_string(),
    }];
    if let Some(summary) = summarize(&input) {
        events.push(HarnessEvent::ToolInput {
