/// [`image_blocks`], as a line of JSON.
fn user_message(text: &str, images: &[Value]) -> String {
    let content: Vec<Value> = std::iter::once(json!({ "type": "text", "text": text }))
        .chain(images.iter().cloned())
        .collect();
    let mut line = json!({
        "type": "user",
        "message": {
            "role": "user",
            "content": content,
        },
    })
    .to_string();
    line.push('\n');
    line
}

