        let (tx, rx) = mpsc::unbounded();
        let feed = Self::new(tx);
        // Something that reads its input until it closes, on every
        // platform: `cat`, or Windows' own `findstr`.
        #[cfg(windows)]
        let mut reader = crate::process::command("findstr");
        #[cfg(windows)]
        reader.arg("x");
        #[cfg(not(windows))]
        let mut reader = crate::process::command("cat");
        let mut cat = reader
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .spawn()
            .unwrap();
        feed.lock().stdin = cat.stdin.take();
        (feed, rx)
    }
}

/// A message for a harness reading `--input-format stream-json`: a user
/// message holding `text`, then `images`, image content blocks from
/// [`image_blocks`], as a line of JSON.
fn user_message(text: &str, images: &[Value]) -> String {
    let content: Vec<Value> = std::iter::once(json!({ "type": "text", "text": text }))
        .chain(images.iter().cloned())
        .collect();
    let mut line = json!({
        "type": "user",
        "message": {
            "role": "user",
            "content": content,
        },
    })
    .to_string();
    line.push('\n');
    line
}

