/// of it is the latest task. It has nothing to click.
fn chain_parent(task_ix: usize, steps: &[&PromptTask], latest: bool, cx: &App) -> AnyElement {
    let theme = cx.theme();
    let color = chat_input::mode_color(group_mode(steps), cx);
